 <div id="project-notes" role="tabpanel" aria-labelledby="tab-notes" hidden>${r.map(t=>{let n=e.notes[`ficha-${t.id}`]||{};return`<details id="project-ficha-${t.id}"><summary>Ficha ${t.id} · ${k(t.title)} · ${Ze(e,`ficha-${t.id}`)}</summary>${[`question`,`argument`,`revision`,`revisionReason`].filter(e=>n[e]?.trim()).map(e=>`<h3>${k(Ee[e])}</h3><p class="preserve">${k(n[e])}</p>`).join(``)||`<p>La ficha todavía no tiene texto.</p>`}${F(`#unidad/${t.id}/argumentar`,`Abrir ficha`)}</details>`}).join(``)}</div>
